"""The symbols' pins a draft needs, read from the libraries through the bridge.

Read-only: each library is brought to the front (opened if it is not) and
its symbols' pin lists read, the same way sch_preview_template reads them,
with the outline of each symbol's graphics (one batched query per symbol):
Altium's part outline, which design_audit_schematic checks for overlaps,
is those graphics and the pins, and the pins alone underestimate it (a
terminal block's box reaches 100 mil past its outer pins).

A symbol's rows are its pins, plus one ``{"_outline": [x0, y0, x1, y1]}``
row when its graphics were read; a pins file may carry the same row.
"""
from __future__ import annotations

import functools
import json
from pathlib import Path
from typing import Any


def needed(plan: dict, sheet: str) -> list[tuple[str, str]]:
    """(library path, lib_ref) of every symbol on the sheet, once each."""
    sheets = [s.get("name") for s in plan.get("sheets") or []]
    sheet = sheet or (sheets[0] if sheets else "main")
    out: list[tuple[str, str]] = []
    for p in plan.get("parts") or []:
        if (p.get("sheet") or "main") != sheet:
            continue
        key = (p.get("lib_path") or "", p["lib_ref"])
        if key not in out:
            out.append(key)
    return out


#: Schematic graphics a symbol is drawn with.
_GRAPHICS = ("eRectangle", "eRoundRectangle", "eLine", "ePolyline", "sch_polygon",
             "sch_arc", "sch_ellipse", "sch_elliptical_arc", "sch_bezier")
_BOX = ("BoundingRectangle.X1", "BoundingRectangle.Y1",
        "BoundingRectangle.X2", "BoundingRectangle.Y2")


def outline_of(replies: list) -> list[int] | None:
    """The union of the graphics' bounding rectangles in query replies."""
    boxes = []
    for reply in replies:
        if not isinstance(reply, dict):
            continue
        for o in reply.get("objects") or []:
            try:
                x0, y0, x1, y1 = (int(round(float(o[k]))) for k in _BOX)
            except (KeyError, TypeError, ValueError):
                continue
            boxes.append((min(x0, x1), min(y0, y1), max(x0, x1), max(y0, y1)))
    if not boxes:
        return None
    return [min(b[0] for b in boxes), min(b[1] for b in boxes),
            max(b[2] for b in boxes), max(b[3] for b in boxes)]


async def _outline(bridge, ref: str) -> list[int] | None:
    from eda_agent.bridge import bulk

    async def one(kind: str):
        return await bridge.send_command_async("generic.query_objects", {
            "scope": f"lib_component:{ref}", "object_type": kind, "filter": "",
            "properties": ",".join(_BOX)})

    replies, _ = await bulk.run_items(bridge, [functools.partial(one, k) for k in _GRAPHICS])
    return outline_of(replies)


async def read_from_bridge(keys: list[tuple[str, str]]) -> tuple[dict, list[str]]:
    from eda_agent.bridge import get_bridge
    from eda_agent.tools.sch_template import _failed, _focus, _send

    bridge = get_bridge()
    symbols: dict[Any, list[dict]] = {}
    problems: list[str] = []
    focused = None
    for lib, ref in sorted(keys):
        if lib and lib != focused:
            reply = await _focus(bridge, lib)
            if _failed(reply):
                problems.append(f"could not open {lib}: {reply.get('error')}")
                continue
            focused = lib
        reply = await _send(bridge, "library.get_pin_list", {"component_name": ref})
        pins = reply.get("pins") if isinstance(reply, dict) else None
        if not isinstance(pins, list) or not pins:
            problems.append(f"no pins read for {ref}" + ("" if lib else " (the plan gives "
                                                          "no lib_path for it)"))
            continue
        rows = list(pins)
        try:
            box = await _outline(bridge, ref)
        except Exception:               # noqa: BLE001 - the pins still draft
            box = None
        if box:
            rows.append({"_outline": box})
        symbols[(lib, ref)] = rows
    return symbols, problems


def read_file(path: str) -> dict:
    """Pins saved as {"symbols": {lib_ref: [rows]}} (or the dict itself)."""
    data = json.loads(Path(path).read_text(encoding="utf-8-sig"))
    return data.get("symbols", data) if isinstance(data, dict) else {}
